<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import { Head, router, useForm } from '@inertiajs/vue3';
const props=defineProps<{wedding:{id:number;name:string};gifts:{id:number;name:string;quantity:number;reserved_quantity:number;reservations:{id:number;guest_name:string;quantity:number;released_at:string|null}[]}[]}>(); const form=useForm({name:'',description:'',quantity:1,reference_url:''}); const releaseForm=useForm({reason:''}); function submit(){form.post(route('weddings.gifts.store',props.wedding.id),{preserveScroll:true,preserveState:true,onSuccess:()=>form.reset()});} function release(id:number){releaseForm.patch(route('weddings.gifts.reservations.release',[props.wedding.id,id]),{preserveScroll:true,preserveState:true,onSuccess:()=>releaseForm.reset()});}
</script>
<template><Head :title="`Regalos · ${wedding.name}`"/><AuthenticatedLayout><template #header><h1 class="font-serif text-3xl">Regalos · {{ wedding.name }}</h1></template><div class="mx-auto grid max-w-5xl gap-6 px-4 py-8 md:grid-cols-2"><section class="rounded-2xl border bg-white p-5"><h2 class="font-serif text-xl">Lista y reservas</h2><article v-for="gift in gifts" :key="gift.id" class="mt-3 border-t pt-3"><b>{{ gift.name }}</b><p class="text-sm">{{ gift.reserved_quantity }}/{{ gift.quantity }} reservados</p><div v-for="reservation in gift.reservations" :key="reservation.id" class="mt-2 text-sm"><span>{{ reservation.guest_name }} · {{ reservation.quantity }} <em v-if="reservation.released_at">(liberada)</em></span><form v-if="!reservation.released_at" class="mt-1 flex gap-2" @submit.prevent="release(reservation.id)"><input v-model="releaseForm.reason" required class="rounded border-stone-300 text-xs" placeholder="Motivo"><button class="rounded border px-2 text-xs">Liberar</button></form></div></article></section><form class="rounded-2xl border bg-white p-5 space-y-3" @submit.prevent="submit"><h2 class="font-serif text-xl">Nuevo regalo</h2><input v-model="form.name" required class="w-full rounded border-stone-300" placeholder="Regalo"><textarea v-model="form.description" class="w-full rounded border-stone-300" placeholder="Descripción"/><input v-model.number="form.quantity" required type="number" min="1" class="w-full rounded border-stone-300"><input v-model="form.reference_url" type="url" maxlength="2000" class="w-full rounded border-stone-300" placeholder="URL opcional"><p class="text-xs text-stone-500">Se admiten enlaces completos de Amazon y otras tiendas, hasta 2,000 caracteres.</p><button :disabled="form.processing" class="rounded bg-rose-800 px-3 py-2 text-sm text-white disabled:opacity-50">Agregar</button></form></div></AuthenticatedLayout></template>
